import {artistProfiles} from './artists.js';
import {galleryOrder,gallerySlots} from './gallery.js';
import {createPortraits} from './portraits.js';
let portraits=createPortraits();
const profile=artistProfiles[new URLSearchParams(location.search).get('artist')]||artistProfiles.asen;
let galleryIds=[];
import {createNeteasePlayer,neteaseSongId} from './player.js';
const $=(s,e=document)=>e.querySelector(s),$$=(s,e=document)=>[...e.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M5 12h14m-5-5 5 5-5 5',right:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',search:'M21 21l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',plus:'M5 12h14M12 5v14',minus:'M5 12h14',reset:'M3 9a9 9 0 1 1 1 9M3 3v6h6',external:'M14 4h6v6m0-6L10 14M10 4H4v16h16v-6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',link:'m9 15 6-6M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',check:'m5 12 4 4L19 6',layers:'m12 3 10 6-10 6L2 9l10-6M2 13l10 6 10-6M2 17l10 6 10-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const dialog=$('#detail-dialog');let catalog,albumMap,trackMap,personMap,toastTimer,revealObserver,player;
const state={gallery:3,journey:{scope:'core',year:'all'},archive:{query:'',year:'all',kind:'all',albumId:'all',page:1},graph:{mode:'artists',year:'all',albumId:'all',query:'',selected:null,zoom:matchMedia('(max-width:600px)').matches?.82:1,panX:0,panY:0}};
const sourceLink=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function openDialog(html){$('#dialog-content').innerHTML=`<div class="dialog-body">${html}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;bindContent(dialog);}
$('.dialog-close').onclick=()=>{dialog.close();clearDetailHash();};
dialog.addEventListener('cancel',()=>clearDetailHash());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){dialog.close();clearDetailHash();}}});
function clearDetailHash(){if(/^#(?:track|album)\//.test(location.hash))history.replaceState(null,'',location.pathname+location.search+'#archive');}
function detailHash(type,id){history.replaceState(null,'',location.pathname+location.search+`#${type}/${encodeURIComponent(id)}`);}
addEventListener('hashchange',()=>{if(!catalog)return;const match=location.hash.match(/^#(track|album)\/(.+)$/);if(match){const id=decodeURIComponent(match[2]);match[1]==='track'?openTrack(id):openAlbum(id);}});
function sectionHeader(kicker,title,note='',actions=''){return `<div class="section-eyebrow">${kicker}</div><div class="section-heading"><h2>${title}</h2>${actions||`<p>${note}</p>`}</div>`;}
function optionsYear(selected,allLabel='所有年份'){return `<option value="all">${allLabel}</option>`+[...new Set(catalog.tracks.map(t=>t.date.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse().map(y=>`<option value="${y}" ${selected===y?'selected':''}>${y}</option>`).join('');}
const duration=ms=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
const names=t=>t.artistIds.map(id=>personMap.get(id)?.name||id).join(' / ');
const monogram=name=>/[\u4e00-\u9fff]/.test(name)?name.match(/[\u4e00-\u9fff]/g).slice(0,2).join(''):name.replace(/[^A-Za-z0-9Ø]/g,'').slice(0,2).toUpperCase();
function listenButton(t,compact=false){return neteaseSongId(t)?`<button class="listen-button ${compact?'compact':''}" data-listen="${t.id}" aria-label="用网易云收听 ${esc(t.title)}" aria-pressed="false"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.5v13l10-6.5z"/></svg>${compact?'':'用网易云收听'}</button>`:`<a class="text-link" href="${esc(t.source)}" target="_blank" rel="noopener noreferrer">前往 Apple Music 收听 ↗</a>`;}
function bindContent(root){$$('[data-album]',root).forEach(b=>b.onclick=()=>openAlbum(b.dataset.album));$$('[data-track]',root).forEach(b=>b.onclick=()=>openTrack(b.dataset.track));$$('[data-person]',root).forEach(b=>b.onclick=()=>openPerson(b.dataset.person));player?.syncButtons();}
function buildPage(){
 const artistConnections=connections(catalog).length;
 $('#app').innerHTML=`<section class="hero" id="top"><div class="artist-pill"><img src="${catalog.artist.portrait}" alt="${esc(catalog.artist.name)}" width="25" height="25">${esc(catalog.artist.name)}<span>ARTIST ARCHIVE ${profile.archive}</span></div><h1><span class="artist-headline">一个 ${esc(catalog.artist.short)}。</span><br><span class="gradient-text">一整个音乐宇宙。</span></h1><p class="hero-lead">从一张唱片，到一位同行。<br>沿着声音的线索，发现每一次连接。</p><div class="hero-actions"><a class="primary" href="#network">探索他的关系网 ${icon('arrow')}</a><a class="text-link" href="#journey">沿时间听下去 ${icon('right')}</a></div><div class="hero-scene" id="hero-scene" aria-label="${esc(catalog.artist.short)} 专辑封面展览"><div class="scene-glow"></div><div class="scene-orbit"></div><div class="scene-orbit second"></div><div class="scene-shadow"></div><div id="hero-albums"></div></div><div class="hero-caption"><button class="round-button" id="hero-prev" aria-label="较新一张专辑">${icon('left')}</button><strong id="hero-album-title"></strong><small id="hero-album-date"></small><button class="round-button" id="hero-next" aria-label="较早一张专辑">${icon('right')}</button></div><div class="hero-dots" id="hero-dots"></div><div class="hero-bottom"><div class="hero-bottom-note">${esc(profile.tagline)}<br><strong>先从一个人，认真听起。</strong></div><div class="hero-facts"><div><b>${catalog.tracks.length}<small> 条</small></b><span>已收录歌曲记录</span></div><div><b>${catalog.coverage.coreAlbums}<small> 张</small></b><span>个人与联合专辑</span></div><div><b>${artistConnections}<small> 个</small></b><span>关联艺人 / 团体署名</span></div><div><b>${catalog.coverage.from.slice(0,4)}<small>—${catalog.coverage.through.slice(0,4)}</small></b><span>当前作品时间跨度</span></div></div></div></section>
 <section class="content-section reveal" id="journey">${sectionHeader('01 / THE DISCOGRAPHY','每一个阶段，<br><span>都有一张唱片。</span>','从早期合作，到新的自我表达。按发行记录，重走这段音乐旅程。',`<div class="heading-actions"><button class="round-button" id="albums-prev" aria-label="向前浏览专辑">${icon('left')}</button><button class="round-button" id="albums-next" aria-label="向后浏览专辑">${icon('right')}</button></div>`)}<div class="journey-tools"><div class="segmented" aria-label="发行分类"><button data-scope="core" class="active" aria-pressed="true">专辑主线</button><button data-scope="group" aria-pressed="false">早期与团体</button><button data-scope="all" aria-pressed="false">全部关联发行</button></div><span class="journey-note" id="journey-count"></span></div><div class="album-rail" id="album-rail" aria-label="发行作品"></div><div class="timeline-strip"><span class="timeline-caption">FOLLOW THE YEARS</span><button data-journey-year="all" class="active">全部</button>${[...new Set(catalog.tracks.map(t=>t.date.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().map(y=>`<button data-journey-year="${y}">${y}</button>`).join('')}</div><p class="section-smallnote">“全部关联发行”包含客串所在的他人专辑；发行页只列出本档案确认有 ${esc(catalog.artist.short)} 署名的歌曲。</p></section>
 <section class="content-section reveal" id="archive">${sectionHeader('02 / EVERY TRACK, A TRACE','把每一首，<span>放回故事里。</span>','按歌名、专辑或创作者搜索。保留不同版本，也保留它们各自的来处。',`<a class="text-link catalog-download" href="${profile.file}" download="${esc(profile.english)}-catalog-${catalog.checkedAt}.json">导出作品档案 ${icon('download')}</a>`)}<div class="archive-panel"><div class="archive-tools"><label class="search-field">${icon('search')}<input id="track-search" type="search" placeholder="搜索歌曲、专辑或创作者" aria-label="搜索歌曲、专辑或创作者"></label><select id="track-year" class="filter-select" aria-label="歌曲年份">${optionsYear('all')}</select><select id="track-kind" class="filter-select" aria-label="歌曲类型"><option value="all">全部记录</option><option value="solo">单人艺人署名</option><option value="collaboration">多人 / 团体署名</option><option value="instrumental">伴奏版本</option><option value="remix">Remix 版本</option></select></div><div class="archive-count"><span id="track-count"></span><button class="clear-filter" id="clear-track-filters">重置筛选</button></div><table class="tracks-table"><thead><tr><th>#</th><th>歌曲</th><th>所在发行</th><th>平台共同署名</th><th>年份</th><th><span class="hide">详情</span></th></tr></thead><tbody id="track-rows"></tbody></table><div class="pagination"><span id="page-summary"></span><div class="pagination-controls"><button class="round-button" id="page-prev" aria-label="上一页">${icon('left')}</button><span id="page-number"></span><button class="round-button" id="page-next" aria-label="下一页">${icon('right')}</button></div></div></div><p class="section-smallnote">${catalog.coverage.neteaseCollected} 条网易云记录 + ${catalog.coverage.appleExtraTracks} 条 Apple Music 补充。数量按平台条目计，包含伴奏及重复发行，不代表独立歌曲总数。日期为所在发行日期。<a href="#sources">查看收录边界 ↗</a></p></section>
 <section class="content-section network-section reveal" id="network"><div class="network-inner">${sectionHeader('03 / CONNECTED BY SOUND',`以 ${esc(catalog.artist.short)} 为中心，<br><span>声音开始彼此相连。</span>`,'一条线，一首共同作品。点开名字，看看这段关系从哪里开始。')}<div class="network-shell"><div class="network-toolbar"><div class="segmented" aria-label="关系类型"><button class="active" data-mode="artists" aria-pressed="true">共同署名</button><button data-mode="credits" aria-pressed="false">幕后创作者</button></div><div class="network-toolbar-right"><select id="network-year" class="filter-select" aria-label="关系年份">${optionsYear('all')}</select><select id="network-album" class="filter-select" aria-label="关系专辑"><option value="all">所有收录作品</option>${catalog.albums.filter(a=>a.core||a.chapter==='团体项目'||['早期合作','早期项目'].includes(a.chapter)).map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></div></div><div class="network-body"><div class="graph-canvas" id="graph-canvas"></div><aside class="network-sidebar" id="connection-detail" aria-live="polite"></aside></div></div><div class="connection-list-tools"><span id="connection-count"></span><label class="search-field">${icon('search')}<input id="connection-search" type="search" placeholder="寻找一个名字" aria-label="搜索关系人物"></label></div><div class="connection-chips" id="connection-chips" aria-label="所有符合筛选的关系署名"></div><p class="section-smallnote">共同署名来自平台艺人栏，可能包含制作人及团体；幕后关系仅来自单曲明确角色。图中最多展示 10 个节点，全部筛选结果可在下方选取。未取得原始署名的合作不会补画连线。</p></div></section>
 <section class="content-section reveal" aria-label="关于这份档案"><div class="editorial-card"><div class="editorial-image"><img src="${catalog.artist.portrait}" alt="网易云音乐艺人页中的 ${esc(catalog.artist.short)} 肖像" loading="lazy" width="1000" height="1000"></div><div class="editorial-copy"><div class="section-eyebrow">MORE THAN A NAME</div><h2>从一个名字，<br>认识一段音乐历程。</h2><p>${esc(profile.intro)}</p><a class="text-link" href="#sources">每一个连接，都能追溯 ${icon('arrow')}</a></div></div></section>
 <section class="content-section reveal" id="sources">${sectionHeader('04 / THE SOURCES MATTER','认真记录，<span>也坦诚留白。</span>','这份档案持续生长。已经找到的与仍待确认的，都在这里。')}<div class="coverage-banner"><span><strong>公开在架目录已读取，历史完整性仍待补齐。</strong><br>${esc(profile.gapSummary)}</span><button class="text-link" id="open-research">查看核查说明 ${icon('external')}</button></div><div class="sources-grid"><article class="source-card"><div class="source-number">${catalog.coverage.neteaseCollected} <small>/ ${catalog.coverage.neteaseReported}</small></div><h3>网易云公开歌曲目录</h3><p>已读取当前艺人目录的全部返回页。包含个人作品、客串与版本记录；${catalog.coverage.listedReleases} 个艺人页发行条目，关联 ${catalog.coverage.associatedNeteaseReleases} 个发行容器。${catalog.coverage.neteaseExcluded?`其中 ${catalog.coverage.neteaseExcluded} 条身份待核记录已隔离，实际收录 ${catalog.coverage.neteaseIncluded} 条。`:""}</p><a class="text-link" href="${esc(catalog.artist.links[0].url)}" target="_blank" rel="noopener noreferrer">前往网易云艺人页 ${icon('external')}</a></article><article class="source-card"><div class="source-number">${catalog.externalReleases.length} <small>项发行对照</small></div><h3>Apple Music 跨平台核对</h3><p>核对专辑日期与曲目数，补充 ${catalog.coverage.appleExtraTracks} 条歌曲记录。不同地区、版本和上架日期分别保留，不强行统一。</p><button class="text-link" id="open-external">查看 ${catalog.externalReleases.length} 项发行记录 ${icon('arrow')}</button></article></div><div class="source-accordions"><details><summary>已发现的版本差异与统计规则</summary><div class="details-content">${catalog.discrepancies.map(d=>`<div class="gap-item"><b>${esc(d.title)}</b><p>${esc(d.detail)}</p><div class="source-links">${d.sources.map((s,i)=>sourceLink(s,`来源 ${i+1}`)).join('')}</div></div>`).join('')}</div></details><details><summary>仍在寻找的作品与早期资料</summary><div class="details-content">${catalog.gaps.map(g=>`<div class="gap-item"><b>${esc(g.year)} · ${esc(g.title)}</b><p>${esc(g.detail)}</p><div class="source-links">${g.sources.map(s=>sourceLink(s.url,s.title)).join('')}</div></div>`).join('')}</div></details><details><summary>署名、图片与使用说明</summary><div class="details-content">作品数据及图片来自网易云音乐、Apple Music 的公开作品资料。单曲署名只保留明确出现的角色，不把专辑级署名下放到每首歌；尚未核验的别名不自动合并。平台内容可能调整，原始发行资料优先于本档案。封面与肖像用于识别音乐人及作品，权利归相应权利人。试听使用网易云官方外链播放器，按需加载且不自动播放；可播范围由平台权限决定。这里不提供音频下载，无法播放时可前往原音乐平台。</div></details></div><div class="source-check-date"><span>最近核查：${esc(catalog.checkedAt)} · 按北京时间处理发行日期</span><span>ARCHIVE ${profile.archive} / ${esc(profile.english)} · MADE FOR THE CULTURE.</span></div></section>`;
 renderGallery();renderJourney();renderArchive();renderNetwork();
 $('#hero-prev').onclick=()=>{state.gallery=Math.max(0,state.gallery-1);renderGallery();};$('#hero-next').onclick=()=>{state.gallery=Math.min(galleryIds.length-1,state.gallery+1);renderGallery();};
 $('#albums-prev').onclick=()=>$('#album-rail').scrollBy({left:-$('#album-rail').clientWidth*.8,behavior:'smooth'});$('#albums-next').onclick=()=>$('#album-rail').scrollBy({left:$('#album-rail').clientWidth*.8,behavior:'smooth'});
 $$('[data-scope]').forEach(b=>b.onclick=()=>{state.journey.scope=b.dataset.scope;$$('[data-scope]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderJourney();});
 $$('[data-journey-year]').forEach(b=>b.onclick=()=>{state.journey.year=b.dataset.journeyYear;$$('[data-journey-year]').forEach(x=>x.classList.toggle('active',x===b));renderJourney();});
 $('#track-search').oninput=e=>{state.archive.query=e.target.value;state.archive.page=1;renderArchive();};$('#track-year').onchange=e=>{state.archive.year=e.target.value;state.archive.page=1;renderArchive();};$('#track-kind').onchange=e=>{state.archive.kind=e.target.value;state.archive.page=1;renderArchive();};
 $('#clear-track-filters').onclick=()=>{state.archive={query:'',year:'all',kind:'all',albumId:'all',page:1};$('#track-search').value='';$('#track-year').value='all';$('#track-kind').value='all';renderArchive();};
 $('#page-prev').onclick=()=>{state.archive.page--;renderArchive();};$('#page-next').onclick=()=>{state.archive.page++;renderArchive();};
 $$('[data-mode]').forEach(b=>b.onclick=()=>{state.graph.mode=b.dataset.mode;state.graph.selected=null;$$('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderNetwork();});
 $('#network-year').onchange=e=>{state.graph.year=e.target.value;state.graph.selected=null;renderNetwork();};$('#network-album').onchange=e=>{state.graph.albumId=e.target.value;state.graph.selected=null;renderNetwork();};$('#connection-search').oninput=e=>{state.graph.query=e.target.value;state.graph.selected=null;renderNetwork();};
 $('#open-external').onclick=openExternal;$('#open-research').onclick=openResearch;
 observeSections();
 if(/^#(track|album)\//.test(location.hash)){const [type,id]=location.hash.slice(1).split('/');type==='track'?openTrack(decodeURIComponent(id)):openAlbum(decodeURIComponent(id));}
}

function renderGallery(){
 $('#hero-albums').innerHTML=gallerySlots(galleryIds,state.gallery).map(({id,offset})=>{
  const a=albumMap.get(id),year=a.date.slice(0,4)||'待核';
  return '<button class="floating-album '+(offset===0?'center':'')+'" data-album="'+a.id+'" style="--offset:'+offset+';--abs:'+Math.abs(offset)+'" aria-label="查看 '+esc(a.title)+' 专辑，'+year+'"><img src="'+esc(a.artwork)+'" alt="'+esc(a.title)+' 封面" width="300" height="300" fetchpriority="'+(offset===0?'high':'auto')+'"><span class="gallery-year" aria-hidden="true">'+year+'</span></button>';
 }).join('');
 const a=albumMap.get(galleryIds[state.gallery]);$('#hero-album-title').textContent=a.title;$('#hero-album-date').textContent=a.date.slice(0,4)+' · '+a.totalTracks+' 首';
 $('#hero-dots').innerHTML=galleryIds.map((id,i)=>'<button class="'+(state.gallery===i?'active':'')+'" data-gallery="'+i+'" aria-label="展示 '+esc(albumMap.get(id).title)+'" aria-pressed="'+(state.gallery===i)+'"></button>').join('');
 $('#hero-prev').disabled=state.gallery===0;$('#hero-next').disabled=state.gallery===galleryIds.length-1;
 $$('[data-gallery]').forEach(b=>b.onclick=()=>{state.gallery=Number(b.dataset.gallery);renderGallery();});bindContent($('#hero-albums'));
}
function renderJourney(){
 const {scope,year}=state.journey,items=catalog.albums.filter(a=>(scope==='all'||scope==='core'&&a.core||scope==='group'&&['早期合作','早期项目','团体项目'].includes(a.chapter))&&(year==='all'||a.date.startsWith(year)));
 $('#journey-count').textContent=`${items.length} 项发行`;
 $('#album-rail').innerHTML=items.length?items.map(a=>`<button class="album-card" data-album="${a.id}"><div class="album-art"><img src="${esc(a.artwork)}" alt="${esc(a.title)} 封面" loading="lazy" width="300" height="300"><span class="album-year">${a.date.slice(0,4)||'待核'}</span><span class="album-open">+</span></div><h3>${esc(a.title)}</h3><p><span>${a.core?a.chapter:esc(a.type)}</span><span>${a.trackIds.length} 首 ${esc(catalog.artist.short)} 署名</span></p></button>`).join(''):'<div class="empty-state" style="width:100%"><strong>这一年，在别处留下了声音。</strong>此分类下暂无收录。试试“全部关联发行”或其他年份。</div>';
 $('#album-rail').scrollLeft=0;bindContent($('#album-rail'));
}
function renderArchive(){
 const rows=filterTracks(catalog,state.archive),size=12,pages=Math.max(1,Math.ceil(rows.length/size));state.archive.page=Math.max(1,Math.min(pages,state.archive.page));const start=(state.archive.page-1)*size;
 $('#track-count').innerHTML=`<b>${rows.length}</b> 条记录${state.archive.albumId!=='all'?` · ${esc(albumMap.get(state.archive.albumId)?.title)}`:''}`;
 $('#track-rows').innerHTML=rows.slice(start,start+size).map((t,i)=>{const a=albumMap.get(t.albumId);return `<tr><td>${String(start+i+1).padStart(2,'0')}</td><td><button class="song-button" data-track="${t.id}"><img class="song-thumb" src="${esc(a.artwork)}" alt="" loading="lazy" width="39" height="39"><span class="song-info"><b>${esc(t.title)}</b><small>${duration(t.duration)} · ${t.kind==='instrumental'?'伴奏版本':esc(t.sourceLabel)}</small></span></button></td><td><button class="cell-truncate" data-album="${a.id}" style="padding:0;max-width:100%;font-size:10px">${esc(a.title)}</button></td><td><span class="cell-truncate" title="${esc(names(t))}" style="font-size:9px">${esc(names(t))}</span></td><td>${t.date.slice(0,4)||'待核'}</td><td>${neteaseSongId(t)?listenButton(t,true):`<button class="table-more" data-track="${t.id}" aria-label="查看 ${esc(t.title)} 详情">${icon('right')}</button>`}</td></tr>`;}).join('')||'<tr><td colspan="6"><div class="empty-state"><strong>还没有找到这段声音。</strong>换个关键词，或重置年份与类型筛选。</div></td></tr>';
 $('#page-summary').textContent=rows.length?`展示 ${start+1}–${Math.min(start+size,rows.length)} 条`:'0 条符合筛选';$('#page-number').textContent=`${state.archive.page} / ${pages}`;$('#page-prev').disabled=state.archive.page===1;$('#page-next').disabled=state.archive.page===pages;bindContent($('#track-rows'));
}
function renderNetwork(){
 const list=connections(catalog,state.graph);if(!list.some(p=>p.id===state.graph.selected))state.graph.selected=list[0]?.id||null;
 const selected=list.find(p=>p.id===state.graph.selected),displayLimit=matchMedia('(max-width:600px)').matches?6:10;let visible=list.slice(0,displayLimit);if(selected&&!visible.some(p=>p.id===selected.id))visible=[...visible.slice(0,displayLimit-1),selected];
 const w=820,h=510,cx=410,cy=245;
 const nodes=visible.map((p,i)=>({...p,x:cx+278*Math.cos(-Math.PI/2+i*2*Math.PI/visible.length),y:cy+163*Math.sin(-Math.PI/2+i*2*Math.PI/visible.length)}));
 $('#graph-canvas').innerHTML=`<div class="graph-grid"></div><div class="graph-corner">${esc(profile.english)} / ${state.graph.mode==='artists'?'SHARED CREDITS':'BEHIND THE SOUND'}</div><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="以 ${esc(catalog.artist.short)} 为中心的署名关系网络"><defs><filter id="soft-shadow" x="-60%" y="-60%" width="220%" height="230%"><feDropShadow dx="0" dy="5" stdDeviation="7" flood-color="#7283b8" flood-opacity=".09"/></filter><clipPath id="portrait-clip"><circle cx="${cx}" cy="${cy}" r="47"/></clipPath><clipPath id="person-portrait-clip"><circle r="25"/></clipPath></defs><g id="graph-transform"><ellipse class="orbit-ring" cx="${cx}" cy="${cy}" rx="278" ry="163"/><ellipse class="orbit-ring" cx="${cx}" cy="${cy}" rx="200" ry="112"/>${nodes.map(p=>`<path class="connection-line ${p.id===state.graph.selected?'active':'dim'}" d="M ${cx} ${cy} Q ${(cx+p.x)/2+15} ${(cy+p.y)/2-12} ${p.x} ${p.y}"/>`).join('')}<g class="center-node" role="button" tabindex="0" aria-label="${esc(catalog.artist.short)} 档案概览" id="center-node"><circle class="center-ring" cx="${cx}" cy="${cy}" r="58"/><circle cx="${cx}" cy="${cy}" r="69" fill="none" stroke="#d8dff5" stroke-width=".8"/><image href="${catalog.artist.portrait}" x="${cx-47}" y="${cy-47}" height="94" width="94" clip-path="url(#portrait-clip)" preserveAspectRatio="xMidYMid slice"/><text class="node-title" x="${cx}" y="${cy+88}" text-anchor="middle">${esc(catalog.artist.short)}</text><text class="node-caption" x="${cx}" y="${cy+104}" text-anchor="middle">THE STARTING POINT</text></g>${nodes.map(p=>`<g class="person-node ${p.id===state.graph.selected?'active':''}" transform="translate(${p.x},${p.y})" data-node="${p.id}" role="button" tabindex="0" aria-label="查看 ${esc(p.name)} 的 ${p.trackIds.length} 条作品连接"><circle class="node-bg" r="27"/><text class="node-monogram" text-anchor="middle" dominant-baseline="central">${esc(monogram(p.name))}</text>${portraits.imageFor(p.id)?`<image class="node-portrait" data-person-portrait="${p.id}" href="${esc(portraits.imageFor(p.id))}" x="-25" y="-25" width="50" height="50" clip-path="url(#person-portrait-clip)" preserveAspectRatio="xMidYMid slice" aria-hidden="true"/>`:String()}<text class="node-title" y="46" text-anchor="middle">${esc(p.name.length>18?p.name.slice(0,17)+'…':p.name)}</text><text class="node-caption" y="60" text-anchor="middle">${p.trackIds.length} 条记录 · ${p.kind==='collective'?'团体署名':state.graph.mode==='artists'?'共同署名':p.roles.slice(0,2).join(' / ')}</text></g>`).join('')}</g></svg>${!list.length?'<div class="network-empty"><strong>这里暂时还没有连接。</strong>试试其他年份、专辑或名字。</div>':''}<div class="graph-legend"><span><i class="legend-dot"></i>${state.graph.mode==='artists'?'平台艺人署名':'单曲明确角色'}</span><span><i class="legend-line"></i>作品连接</span></div><div class="graph-zoom"><button id="zoom-out" aria-label="缩小关系图">${icon('minus')}</button><button id="zoom-reset" aria-label="复位关系图">${icon('reset')}</button><button id="zoom-in" aria-label="放大关系图">${icon('plus')}</button></div>`;
 $('#connection-count').textContent=`${list.length} 个关联署名 · 图中展示 ${visible.length} 个`;
 $('#connection-chips').innerHTML=list.map(p=>`<button class="connection-chip ${p.id===state.graph.selected?'active':''}" data-connection="${p.id}" aria-pressed="${p.id===state.graph.selected}">${esc(p.name)}<small>${p.trackIds.length}</small></button>`).join('');
 const choose=id=>{state.graph.selected=id;renderNetwork();};let moved=false,drag=null;const stage=$('#graph-canvas');portraits.bind(stage);
 $$('[data-node]',stage).forEach(b=>{b.onclick=()=>{if(!moved)choose(b.dataset.node);};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(b.dataset.node);}};});
 $$('[data-connection]').forEach(b=>b.onclick=()=>choose(b.dataset.connection));
 $('#center-node').onclick=()=>openResearch();$('#center-node').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openResearch();}};
 $('#zoom-in').onclick=()=>{state.graph.zoom=Math.min(1.8,state.graph.zoom+.15);transformGraph();};$('#zoom-out').onclick=()=>{state.graph.zoom=Math.max(.45,state.graph.zoom-.15);transformGraph();};$('#zoom-reset').onclick=()=>{state.graph.zoom=matchMedia('(max-width:600px)').matches?.82:1;state.graph.panX=state.graph.panY=0;transformGraph();};
 stage.onpointerdown=e=>{if(e.button!==0||e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,px:state.graph.panX,py:state.graph.panY};moved=false;};
 stage.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>7){moved=true;stage.setPointerCapture(e.pointerId);}if(moved){const s=820/$('svg[viewBox]',stage).getBoundingClientRect().width;state.graph.panX=drag.px+dx*s;state.graph.panY=drag.py+dy*s;transformGraph();}};
 stage.onpointerup=()=>drag=null;stage.onpointercancel=()=>drag=null;stage.onpointerleave=e=>{if(!stage.hasPointerCapture(e.pointerId))drag=null;};
 transformGraph();
 $('#connection-detail').innerHTML=selected?`<div class="connection-selected"><span class="person-badge">${esc(monogram(selected.name))}</span><div><h3>${esc(selected.name)}</h3><p>${esc(selected.roles.join(' / '))}${selected.kind==='collective'?' · 团体':''}</p></div></div><p class="relation-description">与 ${esc(catalog.artist.short)} 的 <strong>${selected.trackIds.length} 条作品连接</strong>。<br>从这些具体的署名记录中，听见交集。</p><div class="connection-tracks">${selected.trackIds.slice(0,8).map(id=>miniTrack(trackMap.get(id))).join('')}</div><button class="connection-all" id="open-selected-person">展开全部作品与依据 ${icon('right')}</button>`:'<div class="empty-state"><strong>连接等待被发现</strong>调整筛选，继续探索。</div>';
 if(selected)$('#open-selected-person').onclick=()=>openPerson(selected.id);bindContent($('#connection-detail'));
}
function transformGraph(){const g=$('#graph-transform');if(g)g.setAttribute('transform',`translate(${410+state.graph.panX} ${245+state.graph.panY}) scale(${state.graph.zoom}) translate(-410 -245)`);}
function miniTrack(t){const a=albumMap.get(t.albumId);return `<div class="mini-track-wrap"><button class="mini-track" data-track="${t.id}"><img src="${esc(a.artwork)}" alt="" loading="lazy" width="33" height="33"><span><b>${esc(t.title)}</b><small>${t.date.slice(0,4)||'待核'} · ${esc(a.title)}</small></span>${icon('right')}</button>${neteaseSongId(t)?listenButton(t,true):''}</div>`;}
function albumTrackRow(t,index){return `<div class="detail-track-row"><small>${String(index+1).padStart(2,'0')}</small><button data-track="${t.id}"><span class="song-info"><b>${esc(t.title)}</b><small>${esc(names(t))}</small></span></button><span class="duration">${duration(t.duration)}</span>${neteaseSongId(t)?listenButton(t,true):''}</div>`;}
function openAlbum(id){
 const a=albumMap.get(id);if(!a){toast('此发行尚未收录');return;}detailHash('album',id);const songs=a.trackIds.map(id=>trackMap.get(id)).filter(Boolean).sort((x,y)=>x.trackNumber-y.trackNumber),versions=catalog.externalReleases.filter(r=>r.relatedAlbumId===id);
 openDialog(`<div class="detail-hero"><img class="detail-art" src="${esc(a.artwork)}" alt="${esc(a.title)} 封面"><div class="detail-copy"><div class="section-eyebrow">${esc(profile.english)} / THE DISCOGRAPHY</div><h2 id="dialog-heading">${esc(a.title)}</h2><p>${a.date||'日期待核'} · ${esc(a.type)}<br>${esc(a.artistNames.join(' / '))}</p></div></div><div class="detail-facts"><span class="detail-pill">${esc(a.chapter)}</span><span class="detail-pill">平台发行共 ${a.totalTracks??'未标明'} 首</span><span class="detail-pill">本档案 ${esc(catalog.artist.short)} 署名 ${songs.length} 首</span></div><div class="detail-label">收录曲目 · 仅展示 ${esc(catalog.artist.short)} 署名记录</div>${songs.map(albumTrackRow).join('')}<div class="evidence-box"><strong>发行记录来源 · ${esc(a.sourceLabel)}</strong>发布日期：${a.date||'日期待核'}。${a.label?`平台厂牌 / 版权字段：${esc(a.label)}。`:''}<br>目录核查日期：${a.checkedAt}。歌曲列表以本档案当前取得的艺人署名记录为准，不能推定他参与整张合作方专辑。<div class="source-links">${sourceLink(a.source,'打开原始发行页')}</div></div>${versions.length?`<div class="detail-label">相关 Apple Music 发行 / 版本记录</div>${versions.map(externalRow).join('')}`:''}<div class="detail-actions"><button class="primary" id="album-in-archive">在目录中查看 ${icon('arrow')}</button><button class="text-link" id="share-detail">复制档案链接 ${icon('link')}</button></div>`);
 $('#album-in-archive').onclick=()=>{state.archive={query:'',year:'all',kind:'all',albumId:id,page:1};$('#track-search').value='';$('#track-year').value='all';$('#track-kind').value='all';renderArchive();dialog.close();history.replaceState(null,'','#archive');$('#archive').scrollIntoView({behavior:'smooth'});};$('#share-detail').onclick=()=>copyText(location.href);
}
function openTrack(id){
 const t=trackMap.get(id);if(!t){toast('此歌曲尚未收录');return;}detailHash('track',id);const a=albumMap.get(t.albumId),grouped=new Map();for(const c of t.credits){if(!grouped.has(c.role))grouped.set(c.role,new Set());grouped.get(c.role).add(c.personId);}
 openDialog(`<div class="detail-hero"><img class="detail-art" src="${esc(a.artwork)}" alt="${esc(a.title)} 封面"><div class="detail-copy"><div class="section-eyebrow">FOLLOW THE CREDITS</div><h2 id="dialog-heading">${esc(t.title)}</h2><p>${t.date||'日期待核'} · ${duration(t.duration)}<br>${esc(a.title)}</p></div></div><div class="track-listen-action">${listenButton(t)}</div><div class="detail-label">平台艺人署名</div><div class="detail-credit"><span>共同署名</span><span>${t.artistIds.map(id=>id===catalog.artist.id?esc(personMap.get(id).name):`<button data-person="${id}">${esc(personMap.get(id).name)}</button>`).join(' / ')}</span></div><div class="detail-label">单曲明确角色</div>${grouped.size?[...grouped.entries()].map(([role,ids])=>`<div class="detail-credit"><span>${esc(role)}</span><span>${[...ids].map(id=>id===catalog.artist.id?esc(personMap.get(id).name):`<button data-person="${id}">${esc(personMap.get(id).name)}</button>`).join(' / ')}</span></div>`).join(''):'<p class="section-smallnote">本次尚未取得可核对的单曲幕后署名，不据专辑或合作方身份补填。</p>'}<div class="evidence-box"><strong>平台可追溯记录 · ${esc(t.sourceLabel)}</strong>艺人栏与幕后角色分别记录。平台显示内容并不等于已取得原始唱片内页；这里不将共同署名全部认定为演唱。<br>记录核查于 ${t.checkedAt}。${t.note?`<br>${esc(t.note)}`:''}<div class="source-links">${sourceLink(t.source,'打开单曲原始页')}${sourceLink(a.source,'打开所在发行页')}</div></div>${t.creditLines.length?`<details class="source-accordions"><summary>查看平台原始署名字段</summary><pre class="raw-credits">${esc(t.creditLines.join('\n'))}</pre></details>`:''}<div class="detail-actions"><button class="primary" data-album="${a.id}">回到这张发行 ${icon('arrow')}</button><button class="text-link" id="share-detail">复制歌曲档案链接 ${icon('link')}</button></div>`);$('#share-detail').onclick=()=>copyText(location.href);
}
function openPerson(id){
 const p=personMap.get(id);if(!p)return;
 const related=catalog.tracks.filter(t=>t.artistIds.includes(id)||t.credits.some(c=>c.personId===id));
 const roles=[...new Set(related.flatMap(t=>[...(t.artistIds.includes(id)?['共同署名']:[]),...t.credits.filter(c=>c.personId===id).map(c=>c.role)]))];
 openDialog(`<div class="detail-copy"><div class="section-eyebrow">${esc(profile.english)} × THE PEOPLE BEHIND</div><h2 id="dialog-heading">${esc(p.name)}</h2><p>仅展示与 ${esc(catalog.artist.short)} 关联的作品，未扩展此音乐人的独立曲库。</p></div><div class="detail-facts"><span class="detail-pill">${related.length} 条相关记录</span>${roles.map(r=>`<span class="detail-pill">${esc(r)}</span>`).join('')}</div><div class="detail-label">作品连接与具体角色</div>${related.map(t=>{const roles=t.credits.filter(c=>c.personId===id).map(c=>c.role);if(t.artistIds.includes(id))roles.unshift('共同署名');return `<div class="detail-track-row"><button data-track="${t.id}"><span class="song-info"><b>${esc(t.title)}</b><small>${t.date||'日期待核'} · ${esc([...new Set(roles)].join(' / '))}</small></span></button><button class="text-link" data-track="${t.id}">查看依据 ${icon('right')}</button></div>`;}).join('')}<div class="evidence-box"><strong>关系来自作品，不来自猜测</strong>同一首歌曲出现多个角色，关系计数只计一条；单曲版与专辑版保留不同平台 ID。尚未核验的别名不自动合并。${p.source?`<div class="source-links">${sourceLink(p.source,'平台艺人页')}</div>`:''}</div>`);
}
function externalRow(r){return `<div class="external-release"><div><b>${esc(r.title)}</b><small>${r.date} · ${r.trackCount} 首 · ${esc(r.sourceLabel)}</small></div>${sourceLink(r.source,'来源')}</div>`;}
function openExternal(){openDialog(`<div class="detail-copy"><div class="section-eyebrow">CROSS-PLATFORM CATALOG</div><h2 id="dialog-heading">跨平台，保留每一种版本。</h2><p>Apple Music 中国区艺人目录返回的 ${catalog.externalReleases.length} 项发行记录。关联记录可能是独立单曲版、地区版或后续上架版本，不以标题强行合并。</p></div>${catalog.discrepancies.map(d=>`<div class="evidence-box"><strong>${esc(d.title)}</strong>${esc(d.detail)}</div>`).join('')}${[...catalog.externalReleases].sort((a,b)=>b.date.localeCompare(a.date)).map(externalRow).join('')}`);}
function openResearch(){openDialog(`<div class="detail-copy"><div class="section-eyebrow">ARCHIVE ${profile.archive} / RESEARCH NOTES</div><h2 id="dialog-heading">已收录，也有待寻找。</h2><p>${esc(catalog.coverage.description)}</p></div><div class="detail-facts"><span class="detail-pill">${catalog.tracks.length} 条歌曲记录</span><span class="detail-pill">${catalog.coverage.coreAlbums} 张核心个人 / 联合项目</span><span class="detail-pill">${catalog.albums.length} 个关联发行容器</span></div><div class="detail-label">现在能确认的收录范围</div><div class="evidence-box"><strong>平台目录分页已读完，历史全量尚未证明</strong>网易云报告 ${catalog.coverage.neteaseReported} 条，实际取得 ${catalog.coverage.neteaseCollected} 个不同歌曲 ID；末页 more=false。${catalog.coverage.neteaseExcluded?`其中 ${catalog.coverage.neteaseExcluded} 条身份待核记录隔离，收录 ${catalog.coverage.neteaseIncluded} 条，不进入身份待核作品的关系网。`:""}另补 ${catalog.coverage.appleExtraTracks} 条 Apple Music 记录。数量按平台记录计算，包含版本，不等于独立原创作品数。<br>当前有日期的发行记录跨度为 ${catalog.coverage.from} 至 ${catalog.coverage.through}。早期下架及未正式发行内容不在这个目录完整性保证内。</div><div class="detail-label">仍待补齐</div>${catalog.gaps.map(g=>`<div class="gap-item"><b style="font-size:12px">${esc(g.title)}</b><p class="section-smallnote">${esc(g.detail)}</p><div class="source-links">${g.sources.map(s=>sourceLink(s.url,s.title)).join('')}</div></div>`).join('')}<div class="detail-actions"><a class="primary" href="${profile.file}" download="${profile.english}-catalog-${catalog.checkedAt}.json">下载结构化档案 ${icon('download')}</a>${catalog.artist.links.map(l=>sourceLink(l.url,l.label)).join('')}</div>`);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('档案链接已复制');}catch{openDialog(`<div class="detail-copy"><h2 id="dialog-heading">复制档案链接</h2><p>浏览器未开放剪贴板，可手动复制。</p></div><textarea class="share-input" readonly>${esc(text)}</textarea>`);$('textarea',dialog).select();}}
function observeSections(){
 revealObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in-view');revealObserver.unobserve(e.target);}},{threshold:.05});$$('.reveal').forEach(el=>revealObserver.observe(el));
 const navObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('.site-header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}},{rootMargin:'-15% 0px -65% 0px'});$$('section[id]').forEach(el=>navObserver.observe(el));
 addEventListener('scroll',()=>{const length=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=`${length>0?scrollY/length*100:0}%`;},{passive:true});
}
async function boot(){try{const [res,portraitData]=await Promise.all([fetch(profile.file),fetch('./people-portraits.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);portraits=createPortraits(portraitData.people);if(!res.ok)throw Error('HTTP '+res.status);catalog=await res.json();document.body.dataset.artist=profile.key;galleryIds=galleryOrder(catalog.albums,profile.galleryIds);state.gallery=0;document.title=`RAP DNA · ${catalog.artist.short} 作品与关系档案`;$('#artist-select').value=profile.key;$('#artist-select').onchange=e=>{const next=new URL(location.href);next.searchParams.set('artist',e.target.value);next.hash='';location.assign(next);};albumMap=new Map(catalog.albums.map(a=>[a.id,a]));trackMap=new Map(catalog.tracks.map(t=>[t.id,t]));personMap=new Map(catalog.people.map(p=>[p.id,p]));player=createNeteasePlayer({tracks:trackMap,albums:albumMap,names,beforeOpen:()=>{if(dialog.open){dialog.close();clearDetailHash();}}});buildPage();}catch(error){$('#app').innerHTML='<div class="load-error"><h1>档案暂时没有打开。</h1><p>请使用 Start-Demo.cmd 启动本地服务，或重新加载页面。</p><button class="primary" id="reload-app">重新加载</button></div>';$('#reload-app').onclick=()=>location.reload();console.error(error);}}
boot();
